(hitTokens / 1e6) * hitRatePer1M +
(missTokens / 1e6) * missRatePer1M +
(completionTokens / 1e6) * outRatePer1M;
const savedCny = (hitTokens / 1e6) * (missRatePer1M - hitRatePer1M);
