function formatDateTimeShort(ts) {
if (!ts) return '-';
const d = new Date(Number(ts));
const pad = (n) => String(n).padStart(2, '0');
return `${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
}
