const personaGlowPalette = [
'rgba(124, 92, 255, 0.17)',
'rgba(229, 193, 133, 0.16)',
'rgba(99, 179, 237, 0.15)',
'rgba(232, 155, 180, 0.15)',
'rgba(110, 203, 185, 0.14)'
];
