const mdNow = buildCurrentSessionMarkdown();
const titleNow = (state.activeSession.title || state.activePersona?.name || '对话记录').slice(0, 28);
triggerBrowserDownload(mdNow, 'text/markdown;charset=utf-8', `${titleNow}_聊天与记忆档案.md`);
