if (turns.length === 0) {
showToast('当前对话还没有聊天记录，先和角色聊上两句再来生成对话长图吧！');
return;
}
const origBtnHtml = dlBtn.innerHTML;
dlBtn.innerHTML = `<span>正在生成长图…</span>`;
const dpr = 2;
const width = 680;
const tmp = document.createElement('canvas');
const tCtx = tmp.getContext('2d');
const blocks = [];
